import * as THREE from 'three';

export function createImg2ThreeJsNightstand(): THREE.Group {
  /*
   * img2threejs-style procedural reconstruction.
   *
   * Coordinate convention:
   *   +X = right
   *   +Y = up
   *   +Z = front
   *
   * Hidden dimensions are explicit estimates derived from the supplied
   * orthogonal product views; they are not measurements from a ground-truth
   * mesh or GLB.
   */
  const EST = {
    overallWidth: 0.810,
    overallDepth: 0.530,
    totalHeight: 0.920,
    bodyWidth: 0.760,
    bodyDepth: 0.500,
    bodyHeight: 0.560,
    sideThickness: 0.024,
    bottomThickness: 0.022,
    topThickness: 0.060,
    backPanelThickness: 0.007,
    backInset: 0.004,
    drawerFrontWidth: 0.710,
    drawerFrontHeight: 0.235,
    drawerFrontThickness: 0.028,
    drawerGap: 0.012,
    drawerBoxDepth: 0.420,
    drawerSideThickness: 0.018,
    drawerBottomThickness: 0.014,
    drawerBackThickness: 0.018,
    legHeight: 0.300,
    legTopRadius: 0.022,
    legBottomRadius: 0.012,
    footHeight: 0.008,
    cableHoleRadius: 0.026,
  };

  const root = new THREE.Group();
  root.name = 'walnut_two_drawer_nightstand';

  root.userData = {
    reconstruction: 'img2threejs-procedural',
    estimatedDimensionsMeters: { ...EST },
    referenceViews: {
      front: 'attached-reference',
      right: 'amazon-berkeley-objects:a644c77b_18',
      rear: 'amazon-berkeley-objects:a644c77b_36',
      left: 'amazon-berkeley-objects:a644c77b_54',
    },
    hiddenRegionConfidence: {
      drawerInterior: 0.55,
      carcassInterior: 0.62,
      underside: 0.58,
      legMounts: 0.70,
      rearConstruction: 0.92,
    },
  };

  const wood = {
    carcass: new THREE.MeshStandardMaterial({
      name: 'walnut_carcass_pbr',
      color: 0x654128,
      roughness: 0.46,
      metalness: 0.0,
    }),
    side: new THREE.MeshStandardMaterial({
      name: 'walnut_side_pbr',
      color: 0x70462b,
      roughness: 0.48,
      metalness: 0.0,
    }),
    top: new THREE.MeshStandardMaterial({
      name: 'walnut_top_pbr',
      color: 0x754a2b,
      roughness: 0.42,
      metalness: 0.0,
    }),
    frontBase: new THREE.MeshStandardMaterial({
      name: 'walnut_drawer_base_pbr',
      color: 0x845633,
      roughness: 0.45,
      metalness: 0.0,
    }),
    veneerA: new THREE.MeshStandardMaterial({
      name: 'walnut_veneer_a_pbr',
      color: 0x8d5c37,
      roughness: 0.44,
      metalness: 0.0,
    }),
    veneerB: new THREE.MeshStandardMaterial({
      name: 'walnut_veneer_b_pbr',
      color: 0x795033,
      roughness: 0.45,
      metalness: 0.0,
    }),
    veneerC: new THREE.MeshStandardMaterial({
      name: 'walnut_veneer_c_pbr',
      color: 0x95643d,
      roughness: 0.44,
      metalness: 0.0,
    }),
    veneerD: new THREE.MeshStandardMaterial({
      name: 'walnut_veneer_d_pbr',
      color: 0x70452c,
      roughness: 0.46,
      metalness: 0.0,
    }),
    leg: new THREE.MeshStandardMaterial({
      name: 'dark_walnut_leg_pbr',
      color: 0x46331f,
      roughness: 0.50,
      metalness: 0.0,
    }),
  };

  const brass = new THREE.MeshStandardMaterial({
    name: 'aged_brushed_brass_pbr',
    color: 0x9b7b4a,
    roughness: 0.25,
    metalness: 0.90,
  });

  const brassDark = new THREE.MeshStandardMaterial({
    name: 'brass_standoff_pbr',
    color: 0x765a32,
    roughness: 0.30,
    metalness: 0.88,
  });

  const backing = new THREE.MeshStandardMaterial({
    name: 'dark_backing_board_pbr',
    color: 0x202021,
    roughness: 0.72,
    metalness: 0.0,
    side: THREE.DoubleSide,
  });

  const screwMaterial = new THREE.MeshStandardMaterial({
    name: 'rear_fastener_dark_metal_pbr',
    color: 0x252525,
    roughness: 0.34,
    metalness: 0.74,
  });

  const footMaterial = new THREE.MeshStandardMaterial({
    name: 'rubber_feet_pbr',
    color: 0x171717,
    roughness: 0.82,
    metalness: 0.0,
  });

  function makeBox(
    name: string,
    width: number,
    height: number,
    depth: number,
    material: THREE.Material,
    bevel = 0
  ): THREE.Mesh {
    const shape = new THREE.Shape();
    shape.moveTo(-width / 2, -height / 2);
    shape.lineTo(width / 2, -height / 2);
    shape.lineTo(width / 2, height / 2);
    shape.lineTo(-width / 2, height / 2);
    shape.closePath();

    const geometry = new THREE.ExtrudeGeometry(shape, {
      depth,
      steps: 1,
      curveSegments: 2,
      bevelEnabled: bevel > 0,
      bevelSegments: 2,
      bevelSize: bevel,
      bevelThickness: bevel,
    });

    geometry.translate(0, 0, -depth / 2);
    geometry.computeVertexNormals();

    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = name;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
  }

  function makePolygonPrism(
    name: string,
    points: Array<[number, number]>,
    thickness: number,
    material: THREE.Material
  ): THREE.Mesh {
    const shape = new THREE.Shape();
    shape.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      shape.lineTo(points[i][0], points[i][1]);
    }
    shape.closePath();

    const geometry = new THREE.ExtrudeGeometry(shape, {
      depth: thickness,
      steps: 1,
      bevelEnabled: false,
      curveSegments: 1,
    });

    geometry.translate(0, 0, -thickness / 2);
    geometry.computeVertexNormals();

    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = name;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
  }

  function addCylinder(
    name: string,
    radius: number,
    height: number,
    material: THREE.Material,
    radialSegments = 20
  ): THREE.Mesh {
    const geometry = new THREE.CylinderGeometry(
      radius,
      radius,
      height,
      radialSegments,
      1,
      false
    );
    geometry.computeVertexNormals();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = name;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
  }

  function addLeg(
    parent: THREE.Group,
    name: string,
    top: THREE.Vector3,
    bottom: THREE.Vector3
  ): void {
    const axis = bottom.clone().sub(top);
    const length = axis.length();
    const direction = axis.clone().normalize();

    const geometry = new THREE.CylinderGeometry(
      EST.legBottomRadius,
      EST.legTopRadius,
      length,
      20,
      1,
      false
    );
    geometry.computeVertexNormals();

    const leg = new THREE.Mesh(geometry, wood.leg);
    leg.name = name;
    leg.position.copy(top).add(bottom).multiplyScalar(0.5);
    leg.quaternion.setFromUnitVectors(
      new THREE.Vector3(0, 1, 0),
      direction
    );
    leg.castShadow = true;
    leg.receiveShadow = true;
    parent.add(leg);

    const foot = addCylinder(
      `${name}_rubber_foot`,
      0.013,
      EST.footHeight,
      footMaterial,
      18
    );
    foot.position.copy(bottom).add(
      direction.clone().multiplyScalar(EST.footHeight * 0.48)
    );
    foot.quaternion.setFromUnitVectors(
      new THREE.Vector3(0, 1, 0),
      direction
    );
    parent.add(foot);
  }

  function addDrawerVeneer(
    parent: THREE.Group,
    prefix: string,
    y: number,
    z: number,
    variant: number
  ): void {
    const w = EST.drawerFrontWidth - 0.012;
    const h = EST.drawerFrontHeight - 0.014;
    const hw = w / 2;
    const hh = h / 2;
    const inset = 0.0022;

    /*
     * Real thin veneer geometry rather than a projected texture.
     * The four major pieces create the characteristic low-contrast
     * diagonal/chevron construction visible on the reference.
     */
    const patterns: Array<Array<[number, number]>> =
      variant === 0
        ? [
            [
              [-hw, hh],
              [-0.145, hh],
              [-0.035, 0.005],
              [-0.205, -hh],
              [-hw, -hh],
            ],
            [
              [-0.145, hh],
              [-0.015, hh],
              [0.145, 0.005],
              [-0.035, 0.005],
              [-0.205, -hh],
            ],
            [
              [-0.015, hh],
              [0.150, hh],
              [0.285, -0.005],
              [0.145, 0.005],
              [-0.035, 0.005],
            ],
            [
              [0.150, hh],
              [hw, hh],
              [hw, -hh],
              [0.285, -0.005],
            ],
          ]
        : [
            [
              [-hw, hh],
              [-0.185, hh],
              [-0.045, -0.005],
              [-0.215, -hh],
              [-hw, -hh],
            ],
            [
              [-0.185, hh],
              [-0.015, hh],
              [0.125, -0.005],
              [-0.045, -0.005],
              [-0.215, -hh],
            ],
            [
              [-0.015, hh],
              [0.185, hh],
              [0.315, -0.005],
              [0.125, -0.005],
            ],
            [
              [0.185, hh],
              [hw, hh],
              [hw, -hh],
              [0.315, -0.005],
            ],
          ];

    const mats = [wood.veneerA, wood.veneerB, wood.veneerC, wood.veneerD];

    patterns.forEach((rawPoints, i) => {
      const points = rawPoints.map(([x, py]) => [
        x,
        py,
      ]) as Array<[number, number]>;

      const piece = makePolygonPrism(
        `${prefix}_veneer_piece_${i + 1}`,
        points,
        0.0018,
        mats[(i + variant) % mats.length]
      );
      piece.position.set(0, y, z + inset + i * 0.00003);
      parent.add(piece);
    });

    /*
     * Small irregular central darker veneer joints emulate the naturally
     * darker walnut transitions visible around the pulls.
     */
    const knot = makePolygonPrism(
      `${prefix}_central_walnut_joint`,
      [
        [-0.024, 0.025],
        [0.012, 0.031],
        [0.031, 0.009],
        [0.017, -0.025],
        [-0.014, -0.034],
        [-0.032, -0.006],
      ],
      0.0020,
      wood.veneerD
    );
    knot.position.set(variant === 0 ? -0.015 : 0.018, y, z + inset + 0.0003);
    knot.scale.set(0.95, 1.15, 1);
    parent.add(knot);
  }

  function addDrawer(
    parent: THREE.Group,
    index: number,
    centerY: number
  ): void {
    const drawer = new THREE.Group();
    drawer.name = `drawer_${index}`;
    drawer.userData = {
      editable: true,
      openAxis: 'z',
      openDistance: 0.32,
    };
    parent.add(drawer);

    const frontZ = EST.overallDepth / 2 + 0.003;

    const front = makeBox(
      `drawer_${index}_front`,
      EST.drawerFrontWidth,
      EST.drawerFrontHeight,
      EST.drawerFrontThickness,
      wood.frontBase,
      0.0025
    );
    front.position.set(0, centerY, frontZ);
    drawer.add(front);

    addDrawerVeneer(
      drawer,
      `drawer_${index}`,
      centerY,
      frontZ + EST.drawerFrontThickness / 2,
      index === 1 ? 0 : 1
    );

    const innerWidth = EST.drawerFrontWidth - 0.032;
    const boxDepth = EST.drawerBoxDepth;
    const boxCenterZ = 0.006;
    const boxHeight = EST.drawerFrontHeight - 0.030;

    const leftSide = makeBox(
      `drawer_${index}_left_side`,
      EST.drawerSideThickness,
      boxHeight,
      boxDepth,
      wood.carcass,
      0.001
    );
    leftSide.position.set(
      -innerWidth / 2 + EST.drawerSideThickness / 2,
      centerY,
      boxCenterZ
    );
    drawer.add(leftSide);

    const rightSide = makeBox(
      `drawer_${index}_right_side`,
      EST.drawerSideThickness,
      boxHeight,
      boxDepth,
      wood.carcass,
      0.001
    );
    rightSide.position.set(
      innerWidth / 2 - EST.drawerSideThickness / 2,
      centerY,
      boxCenterZ
    );
    drawer.add(rightSide);

    const bottom = makeBox(
      `drawer_${index}_bottom`,
      innerWidth,
      EST.drawerBottomThickness,
      boxDepth,
      wood.carcass,
      0.001
    );
    bottom.position.set(
      0,
      centerY - boxHeight / 2 + EST.drawerBottomThickness / 2,
      boxCenterZ
    );
    drawer.add(bottom);

    const rear = makeBox(
      `drawer_${index}_rear`,
      innerWidth,
      boxHeight,
      EST.drawerBackThickness,
      wood.carcass,
      0.001
    );
    rear.position.set(
      0,
      centerY,
      boxCenterZ - boxDepth / 2 + EST.drawerBackThickness / 2
    );
    drawer.add(rear);

    const runnerY = centerY - boxHeight / 2 - 0.004;
    const runnerDepth = boxDepth * 0.88;

    const runnerL = makeBox(
      `drawer_${index}_left_runner`,
      0.012,
      0.012,
      runnerDepth,
      screwMaterial,
      0.001
    );
    runnerL.position.set(-innerWidth / 2 + 0.002, runnerY, 0.005);
    drawer.add(runnerL);

    const runnerR = makeBox(
      `drawer_${index}_right_runner`,
      0.012,
      0.012,
      runnerDepth,
      screwMaterial,
      0.001
    );
    runnerR.position.set(innerWidth / 2 - 0.002, runnerY, 0.005);
    drawer.add(runnerR);

    addPull(drawer, `drawer_${index}_pull`, centerY, frontZ + 0.019);
  }

  function addPull(
    parent: THREE.Group,
    name: string,
    y: number,
    frontSurfaceZ: number
  ): void {
    const pull = new THREE.Group();
    pull.name = name;
    parent.add(pull);

    const handleWidth = 0.115;
    const handleHeight = 0.042;
    const handleDepth = 0.017;

    const handle = makeBox(
      `${name}_handle`,
      handleWidth,
      handleHeight,
      handleDepth,
      brass,
      0.004
    );
    handle.position.set(0, y, frontSurfaceZ + 0.009);
    pull.add(handle);

    const postSpacing = 0.073;
    [-1, 1].forEach((side) => {
      const post = addCylinder(
        `${name}_standoff_${side < 0 ? 'left' : 'right'}`,
        0.0085,
        0.018,
        brassDark,
        18
      );
      post.rotation.x = Math.PI / 2;
      post.position.set(
        side * postSpacing / 2,
        y,
        frontSurfaceZ + 0.002
      );
      pull.add(post);

      const screwCap = addCylinder(
        `${name}_screw_cap_${side < 0 ? 'left' : 'right'}`,
        0.0048,
        0.0025,
        brass,
        16
      );
      screwCap.rotation.x = Math.PI / 2;
      screwCap.position.set(
        side * postSpacing / 2,
        y,
        frontSurfaceZ - 0.001
      );
      pull.add(screwCap);
    });
  }

  // -------------------------------------------------------------------------
  // Carcass
  // -------------------------------------------------------------------------

  const carcass = new THREE.Group();
  carcass.name = 'carcass';
  root.add(carcass);

  const bodyBottom = 0.300;
  const bodyTop = bodyBottom + EST.bodyHeight;
  const sideDepth = EST.bodyDepth;

  const leftSide = makeBox(
    'carcass_left_side',
    EST.sideThickness,
    EST.bodyHeight,
    sideDepth,
    wood.side,
    0.002
  );
  leftSide.position.set(
    -EST.bodyWidth / 2 + EST.sideThickness / 2,
    bodyBottom + EST.bodyHeight / 2,
    0
  );
  carcass.add(leftSide);

  const rightSide = makeBox(
    'carcass_right_side',
    EST.sideThickness,
    EST.bodyHeight,
    sideDepth,
    wood.side,
    0.002
  );
  rightSide.position.set(
    EST.bodyWidth / 2 - EST.sideThickness / 2,
    bodyBottom + EST.bodyHeight / 2,
    0
  );
  carcass.add(rightSide);

  const bottomPanel = makeBox(
    'carcass_bottom_panel',
    EST.bodyWidth - EST.sideThickness * 2,
    EST.bottomThickness,
    EST.bodyDepth - 0.010,
    wood.carcass,
    0.0015
  );
  bottomPanel.position.set(
    0,
    bodyBottom + EST.bottomThickness / 2,
    0.002
  );
  carcass.add(bottomPanel);

  const upperRail = makeBox(
    'carcass_upper_front_rail',
    EST.bodyWidth - EST.sideThickness * 2,
    0.028,
    0.045,
    wood.carcass,
    0.0015
  );
  upperRail.position.set(
    0,
    bodyTop - 0.019,
    EST.bodyDepth / 2 - 0.022
  );
  carcass.add(upperRail);

  const lowerRail = makeBox(
    'carcass_lower_front_rail',
    EST.bodyWidth - EST.sideThickness * 2,
    0.026,
    0.040,
    wood.carcass,
    0.0015
  );
  lowerRail.position.set(
    0,
    bodyBottom + 0.030,
    EST.bodyDepth / 2 - 0.020
  );
  carcass.add(lowerRail);

  // Subtle dark recesses behind the drawer gaps are real recessed members.
  const upperDrawerGapBacking = makeBox(
    'upper_drawer_gap_recess',
    EST.drawerFrontWidth - 0.002,
    EST.drawerGap + 0.006,
    0.010,
    screwMaterial,
    0.0005
  );
  upperDrawerGapBacking.position.set(
    0,
    0.580,
    EST.bodyDepth / 2 - 0.006
  );
  carcass.add(upperDrawerGapBacking);

  const lowerDrawerGapBacking = makeBox(
    'lower_drawer_gap_recess',
    EST.drawerFrontWidth - 0.002,
    0.018,
    0.010,
    screwMaterial,
    0.0005
  );
  lowerDrawerGapBacking.position.set(
    0,
    0.326,
    EST.bodyDepth / 2 - 0.006
  );
  carcass.add(lowerDrawerGapBacking);

  // -------------------------------------------------------------------------
  // Drawers
  // -------------------------------------------------------------------------

  const drawers = new THREE.Group();
  drawers.name = 'drawers';
  root.add(drawers);

  const drawerLowerY = 0.4565;
  const drawerUpperY = 0.7035;

  addDrawer(drawers, 1, drawerUpperY);
  addDrawer(drawers, 2, drawerLowerY);

  // -------------------------------------------------------------------------
  // Top slab
  // -------------------------------------------------------------------------

  const topGroup = new THREE.Group();
  topGroup.name = 'top_assembly';
  root.add(topGroup);

  const top = makeBox(
    'top_slab',
    EST.overallWidth,
    EST.topThickness,
    EST.overallDepth,
    wood.top,
    0.006
  );
  top.position.set(
    0,
    bodyTop + EST.topThickness / 2,
    0.0
  );
  topGroup.add(top);

  /*
   * Slightly darker solid front edge band. This is an actual thin wood member,
   * not a painted line, and follows the visible heavy front edge of the top.
   */
  const topFrontEdge = makeBox(
    'top_front_edge_band',
    EST.overallWidth - 0.010,
    0.035,
    0.016,
    wood.carcass,
    0.002
  );
  topFrontEdge.position.set(
    0,
    bodyTop + 0.021,
    EST.overallDepth / 2 + 0.004
  );
  topGroup.add(topFrontEdge);

  // -------------------------------------------------------------------------
  // Rear panel with physical cable-hole geometry
  // -------------------------------------------------------------------------

  const rear = new THREE.Group();
  rear.name = 'rear_assembly';
  root.add(rear);

  const panelWidth = EST.bodyWidth - 0.012;
  const panelHeight = EST.bodyHeight - 0.020;
  const panelBottom = bodyBottom + 0.010;
  const panelCenterY = panelBottom + panelHeight / 2;
  const panelZ =
    -EST.bodyDepth / 2 - EST.backInset - EST.backPanelThickness / 2;

  const panelShape = new THREE.Shape();
  panelShape.moveTo(-panelWidth / 2, -panelHeight / 2);
  panelShape.lineTo(panelWidth / 2, -panelHeight / 2);
  panelShape.lineTo(panelWidth / 2, panelHeight / 2);
  panelShape.lineTo(-panelWidth / 2, panelHeight / 2);
  panelShape.closePath();

  const cableHole = new THREE.Path();
  cableHole.absarc(
    0,
    panelHeight * 0.305,
    EST.cableHoleRadius,
    0,
    Math.PI * 2,
    true
  );
  panelShape.holes.push(cableHole);

  const rearGeometry = new THREE.ShapeGeometry(panelShape, 32);
  rearGeometry.computeVertexNormals();

  const rearPanel = new THREE.Mesh(rearGeometry, backing);
  rearPanel.name = 'rear_dark_backing_panel_with_cable_hole';
  rearPanel.position.set(0, panelCenterY, panelZ);
  rearPanel.castShadow = true;
  rearPanel.receiveShadow = true;
  rear.add(rearPanel);

  // Actual visible thickness ring around the cable opening.
  const cableRing = new THREE.Mesh(
    new THREE.RingGeometry(
      EST.cableHoleRadius * 0.82,
      EST.cableHoleRadius,
      32
    ),
    backing
  );
  cableRing.name = 'rear_cable_hole_inner_edge';
  cableRing.rotation.x = Math.PI / 2;
  cableRing.position.set(
    0,
    panelCenterY + panelHeight * 0.305,
    panelZ + 0.004
  );
  rear.add(cableRing);

  /*
   * Fasteners are individually modeled, positioned at the locations visible
   * from the rear reference. Small discrepancies are intentionally kept as
   * explicit estimated construction details rather than hidden assumptions.
   */
  const fastenerPositions: Array<[number, number]> = [
    [-panelWidth / 2 + 0.012, -panelHeight / 2 + 0.012],
    [0, -panelHeight / 2 + 0.012],
    [panelWidth / 2 - 0.012, -panelHeight / 2 + 0.012],
    [-panelWidth / 2 + 0.012, 0],
    [panelWidth / 2 - 0.012, 0],
    [-panelWidth / 2 + 0.012, panelHeight / 2 - 0.012],
    [0, panelHeight / 2 - 0.012],
    [panelWidth / 2 - 0.012, panelHeight / 2 - 0.012],
  ];

  fastenerPositions.forEach(([x, y], i) => {
    const screw = addCylinder(
      `rear_fastener_${i + 1}`,
      0.0038,
      0.003,
      screwMaterial,
      14
    );
    screw.rotation.x = Math.PI / 2;
    screw.position.set(
      x,
      panelCenterY + y,
      panelZ - 0.004
    );
    rear.add(screw);
  });

  // -------------------------------------------------------------------------
  // Four tapered, splayed legs
  // -------------------------------------------------------------------------

  const legs = new THREE.Group();
  legs.name = 'four_tapered_splayed_legs';
  root.add(legs);

  const legTopY = bodyBottom + 0.002;
  const legBottomY = 0.014;

  addLeg(
    legs,
    'front_left_leg',
    new THREE.Vector3(-0.285, legTopY, 0.175),
    new THREE.Vector3(-0.335, legBottomY, 0.230)
  );

  addLeg(
    legs,
    'front_right_leg',
    new THREE.Vector3(0.285, legTopY, 0.175),
    new THREE.Vector3(0.335, legBottomY, 0.230)
  );

  addLeg(
    legs,
    'rear_left_leg',
    new THREE.Vector3(-0.285, legTopY, -0.175),
    new THREE.Vector3(-0.335, legBottomY, -0.230)
  );

  addLeg(
    legs,
    'rear_right_leg',
    new THREE.Vector3(0.285, legTopY, -0.175),
    new THREE.Vector3(0.335, legBottomY, -0.230)
  );

  // -------------------------------------------------------------------------
  // Editable sockets / animation metadata
  // -------------------------------------------------------------------------

  root.userData.sockets = {
    drawer1_pull_center: new THREE.Vector3(0, drawerUpperY, EST.overallDepth / 2 + 0.045),
    drawer2_pull_center: new THREE.Vector3(0, drawerLowerY, EST.overallDepth / 2 + 0.045),
    cable_hole_center: new THREE.Vector3(
      0,
      panelCenterY + panelHeight * 0.305,
      -EST.bodyDepth / 2 - EST.backInset - EST.backPanelThickness
    ),
    leg_mounts: [
      new THREE.Vector3(-0.285, legTopY, 0.175),
      new THREE.Vector3(0.285, legTopY, 0.175),
      new THREE.Vector3(-0.285, legTopY, -0.175),
      new THREE.Vector3(0.285, legTopY, -0.175),
    ],
  };

  root.userData.nodes = {
    carcass,
    drawers,
    topGroup,
    rear,
    legs,
  };

  root.traverse((object) => {
    if (object instanceof THREE.Mesh) {
      object.userData.editablePart = true;
      object.frustumCulled = true;
    }
  });

  return root;
}
